3	import (
4		"errors"
5		"os"
6		"reflect"
7		"testing"
8	)
9	
10	// 本文件为整批转让补充"保存失败"场景的回归保障：业务检查全部通过后，
11	// 在本次内容原子替换已保存数据之前写入失败（原登记册仍可正常读取）时，
12	// 整批必须整体失败、不留任何部分转让，请求号与历史序号都不被消耗；
13	// 保存条件恢复后用完全相同的请求号、原因与条目重提，必须完整执行一次，
14	// 而不是回放一个实际没有保存的成功结果或报请求号冲突。
15	//
16	// 失败注入方式：在临时文件路径 .registry.json.tmp 上预先建一个目录，
17	// save 在 OpenFile 阶段即以 EISDIR 失败——失败发生在 rename 替换
18	// registry.json 之前，原快照完好可读；删除该目录即恢复保存条件。该方式
19	// 不依赖文件权限（root 也生效），也不会触碰原数据文件。
20	
21	// batchSaveFailureReq 是各用例共用的整批请求：至少两件、接收账户互不相同，
22	// 且包含带版税规则的藏品（i1/i3 属 s1：carol 10% + dave 5%；i2 属 s2：
23	// carol 100%）。各件期望持有人 bob、版本 1。
24	func batchSaveFailureReq() TransferBatchRequest {
25		return tbtReq("rb-fail",
26			tbtEntry("i1", "carol", 1, 10000),
27			tbtEntry("i2", "dave", 1, 333),
28			tbtEntry("i3", "alice", 1, 500),
29		)
30	}
31	
32	// seedBatchSaveFailureWorld 建立一个已经存在成功转让与应付记录的登记册：
33	// setupBatchTransferWorld 发行 i1..i5（历史序号 1..5）后，再由 alice 发行
34	// i6（s1，序号 6）给 bob，并由 bob 以 10000 分把 i6 转让给 alice（序号 7）。
35	// 因此失败发生前最后一条历史序号是 7；carol/dave 各有一条序号 7 的应付
36	// （1000/500），余款 8500 归 bob。清单外藏品 i4（bob，版本 1）、i5
37	// （carol，版本 1）与已易手的 i6（alice，版本 2）用于核对失败不外溢。
38	func seedBatchSaveFailureWorld(t *testing.T, r *Registry) {
39		t.Helper()
40		setupBatchTransferWorld(t, r)
41		if _, err := r.Issue(IssueRequest{
42			Operator: "alice", Reason: "首发", RequestID: "ri-i6",
43			ItemID: "i6", SeriesID: "s1", BatchNo: "b1",
44			Metadata: "元-i6", HolderID: "bob",
45		}); err != nil {
46			t.Fatal(err)
47		}
48		if _, err := r.Transfer(TransferRequest{
49			Operator: "bob", Reason: "先存一笔成功转让", RequestID: "rt-prior", ItemID: "i6",
50			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice", Price: 10000,
51		}); err != nil {
52			t.Fatal(err)
53		}
54	}
55	
56	// blockBatchSave 让下一次 commit 的写入在替换数据文件之前确定性失败。
57	func blockBatchSave(t *testing.T, r *Registry) {
58		t.Helper()
59		if err := os.MkdirAll(tempFile(r.dir), dirMode); err != nil {
60			t.Fatalf("注入保存失败: %v", err)
61		}
62	}
63	
64	// restoreBatchSave 恢复保存条件：移除占据临时文件路径的目录。
65	func restoreBatchSave(t *testing.T, r *Registry) {
66		t.Helper()
67		if err := os.RemoveAll(tempFile(r.dir)); err != nil {
68			t.Fatalf("恢复保存条件: %v", err)
69		}
70	}
71	
72	// businessSentinels 是保存错误必须有别于业务拒绝的哨兵集合。
73	var businessSentinels = []error{
74		ErrConflict, ErrAccountInactive, ErrSameAccount, ErrForbidden,
75		ErrRequestConflict, ErrInvalidArgument, ErrNotFound, ErrSeriesSealed,
76	}
77	
78	// assertSaveFailureError 确认返回的是保存错误而非任何业务拒绝。
79	func assertSaveFailureError(t *testing.T, err error) {
80		t.Helper()
81		if err == nil {
82			t.Fatal("保存失败必须返回错误，却返回了 nil")
83		}
84		for _, s := range businessSentinels {
85			if errors.Is(err, s) {
86				t.Fatalf("返回的应是保存错误，不能是业务拒绝 %v: %v", s, err)
87			}
88		}
89	}
90	
91	// assertBatchStillPending 在（失败返回后的）同一个已打开登记册上核对：
92	// 整批如同从未发生，且失败前已有的内容、顺序与金额完整保留。
93	func assertBatchStillPending(t *testing.T, r *Registry) {
94		t.Helper()
95		req := batchSaveFailureReq()
96	
97		// 清单内每件仍属原持有人 bob，持有版本没有增加。
98		for _, id := range []string{"i1", "i2", "i3"} {
99			h, err := r.GetHolding(id)
100			if err != nil {
101				t.Fatalf("GetHolding %s: %v", id, err)
102			}
103			if h.OwnerID != "bob" || h.Version != 1 {
104				t.Fatalf("失败后 %s 持有被改变: %+v", id, h)
105			}
106			hist, err := r.History(id)
107			if err != nil {
108				t.Fatalf("History %s: %v", id, err)
109			}
110			if len(hist) != 1 || hist[0].Kind != "issue" {
111				t.Fatalf("失败后 %s 历史多出本次请求: %+v", id, hist)
112			}
113			for _, e := range hist {
114				if e.RequestID == req.RequestID {
115					t.Fatalf("失败后 %s 历史出现请求号 %s: %+v", id, req.RequestID, e)
116				}
117			}
118		}
119	
120		// 历史序号不被消耗：下一条仍是 8（失败前最后一条为 7）。
121		if r.state.NextSeq != 7 {
122			t.Fatalf("NextSeq = %d，失败不应消耗历史序号，仍应为 7", r.state.NextSeq)
123		}
124		// 请求号未被占用：请求记录中没有这一次失败。
125		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
126			t.Fatal("失败的整批不应登记请求结果，请求号应仍可使用")
127		}
128	
129		// 相关收款账户不能多出本次转让的应付明细：旧记录（序号 7）的内容、
130		// 顺序与金额都应保留。
131		wantCarol := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 1000, Amount: 1000}}
132		wantDave := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 500, Amount: 500}}
133		carolPay, err := r.PayablesOf("carol")
134		if err != nil {
135			t.Fatal(err)
136		}
137		if !reflect.DeepEqual(carolPay, wantCarol) {
138			t.Fatalf("carol 应付 = %+v, want %+v", carolPay, wantCarol)
139		}
140		davePay, err := r.PayablesOf("dave")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if !reflect.DeepEqual(davePay, wantDave) {
145			t.Fatalf("dave 应付 = %+v, want %+v", davePay, wantDave)
146		}
