211				{AccountID: "dave", Rate: 500, Amount: 25},
212			}},
213		}
214		for i, w := range want {
215			it := res.Items[i]
216			if it.ItemID != w.item || it.FromID != "bob" || it.ToID != w.to ||
217				it.Version != w.ver || it.TxSeq != w.seq ||
