239				t.Fatal(err)
240			}
241			if len(hist) != 2 {
242				t.Fatalf("%s 历史应为发行+本次转让两条，得到 %+v", w.item, hist)
243			}
244			last := hist[1]
245			if last.Seq != w.seq || last.Kind != "transfer" ||
246				last.Operator != "bob" || last.Reason != req.Reason || last.RequestID != req.RequestID ||
247				last.FromID != "bob" || last.ToID != w.to ||
248				last.FromVersion != 1 || last.ToVersion != w.ver || last.AuthID != "" {
249				t.Fatalf("%s 本次转让历史 = %+v", w.item, last)
250			}
251			tr, err := r.TransferRoyalty(w.seq)
252			if err != nil {
253				t.Fatalf("TransferRoyalty %d: %v", w.seq, err)
254			}
255			if tr.ItemID != w.item || tr.Price != w.price || tr.Remainder != w.rem ||
256				tr.OwnerID != "bob" || !reflect.DeepEqual(tr.Payables, w.payables) {
257				t.Fatalf("%s 版税记录 = %+v, payables want %+v", w.item, tr, w.payables)
258			}
259		}
260	
261		// 按收款账户查询：只能增加真正成功的三笔（序号 8/9/10）明细，旧的
262		// 序号 7 记录内容、顺序、金额保持不变。
263		wantCarol := []PayableEntry{
264			{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 1000, Amount: 1000},
265			{TxSeq: 8, ItemID: "i1", Price: 10000, Rate: 1000, Amount: 1000},
266			{TxSeq: 9, ItemID: "i2", Price: 333, Rate: 10000, Amount: 333},
267			{TxSeq: 10, ItemID: "i3", Price: 500, Rate: 1000, Amount: 50},
268		}
269		wantDave := []PayableEntry{
270			{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 500, Amount: 500},
271			{TxSeq: 8, ItemID: "i1", Price: 10000, Rate: 500, Amount: 500},
272			{TxSeq: 10, ItemID: "i3", Price: 500, Rate: 500, Amount: 25},
273		}
274		if carolPay, err := r.PayablesOf("carol"); err != nil || !reflect.DeepEqual(carolPay, wantCarol) {
275			t.Fatalf("carol 应付 = %+v, err %v, want %+v", carolPay, err, wantCarol)
276		}
277		if davePay, err := r.PayablesOf("dave"); err != nil || !reflect.DeepEqual(davePay, wantDave) {
278			t.Fatalf("dave 应付 = %+v, err %v, want %+v", davePay, err, wantDave)
279		}
280		// alice 只是接收账户，不是任何系列的收款人：不应多出任何明细。
281		if alicePay, err := r.PayablesOf("alice"); err != nil || len(alicePay) != 0 {
282			t.Fatalf("非收款人 alice 应付 = %+v, err %v, 应为空", alicePay, err)
283		}
284	
285		// 最后一条历史序号为 10，8/9/10 连续无空洞（NextSeq 记录最后已分配
286		// 的序号）。
287		if r.state.NextSeq != 10 {
288			t.Fatalf("NextSeq = %d, want 10", r.state.NextSeq)
289		}
290	
291		// 再用完全相同的请求号重提：回放首次成功结果，不再执行第二次。
292		replay, err := r.TransferBatch(req)
293		if err != nil {
294			t.Fatalf("成功后重提应回放: %v", err)
295		}
296		if !replay.Replayed || len(replay.Items) != 3 {
297			t.Fatalf("成功后重提 = %+v", replay)
298		}
299		for i := range want {
300			if replay.Items[i].ItemID != res.Items[i].ItemID ||
301				replay.Items[i].TxSeq != res.Items[i].TxSeq ||
302				replay.Items[i].Version != res.Items[i].Version {
303				t.Fatalf("回放内容与首次成功不一致: %+v vs %+v", replay.Items[i], res.Items[i])
304			}
305			h, _ := r.GetHolding(want[i].item)
306			if h.Version != want[i].ver {
307				t.Fatalf("回放又增加了持有版本: %+v", h)
308			}
309			if hist, _ := r.History(want[i].item); len(hist) != 2 {
310				t.Fatalf("回放又产生了历史: %+v", hist)
311			}
312		}
313		if carolPay, _ := r.PayablesOf("carol"); len(carolPay) != len(wantCarol) {
314			t.Fatalf("回放又产生了应付明细: %+v", carolPay)
315		}
316		return res
317	}
318	
319	// TestTransferBatchSaveFailureSameRegistry 覆盖核心场景：保存失败后调用者
320	// 继续使用同一个已打开的登记册，全部状态停留在整批之前；保存条件恢复后
321	// 用原请求号重提完整执行一次。
322	func TestTransferBatchSaveFailureSameRegistry(t *testing.T) {
323		r := mustCreate(t, tempDir(t))
324		seedBatchSaveFailureWorld(t, r)
325		req := batchSaveFailureReq()
326	
327		// 业务参数完全合规（账户登记可用、接收人不同、期望持有人与版本相符、
328		// 价款非负），失败只可能来自写入阶段。
329		blockBatchSave(t, r)
330		res, err := r.TransferBatch(req)
331		assertSaveFailureError(t, err)
332		if len(res.Items) != 0 || res.ItemID != "" || res.Replayed || res.Err != nil {
333			t.Fatalf("保存失败必须整体失败，不能返回任何一件已转让成功的结果: %+v", res)
334		}
335	
336		// 同一个已打开的登记册上立即查询：整批从未发生，旧记录完整保留。
337		assertBatchStillPending(t, r)
338	
339		// 保存条件恢复后用完全相同的请求号、原因和条目再次提交：原来的期望
340		// 持有人与版本仍然有效，整批完整执行一次（非回放、无请求号冲突）。
341		restoreBatchSave(t, r)
342		assertBatchRetrySuccess(t, r, req)
343	
344		// 清单外藏品在失败与重试之后仍保持原状。
345		i4, _ := r.GetHolding("i4")
346		if i4.OwnerID != "bob" || i4.Version != 1 {
347			t.Fatalf("清单外 i4 最终受影响: %+v", i4)
348		}
349		i5, _ := r.GetHolding("i5")
350		if i5.OwnerID != "carol" || i5.Version != 1 {
351			t.Fatalf("清单外 i5 最终受影响: %+v", i5)
352		}
353		i6, _ := r.GetHolding("i6")
354		if i6.OwnerID != "alice" || i6.Version != 2 {
355			t.Fatalf("清单外 i6 最终受影响: %+v", i6)
356		}
357	}
358	
359	// TestTransferBatchSaveFailureRetryAfterReopen 覆盖磁盘视角：保存失败后
360	// 原登记册仍可正常读取——关闭后重新 Open，看到的仍是整批前状态；此时用
361	// 原请求号重提同样完整执行一次，而不是回放未保存的成功。
362	func TestTransferBatchSaveFailureRetryAfterReopen(t *testing.T) {
363		dir := tempDir(t)
364		r := mustCreate(t, dir)
365		t.Cleanup(func() { _ = r.Close() })
366		seedBatchSaveFailureWorld(t, r)
367		req := batchSaveFailureReq()
368	
369		blockBatchSave(t, r)
370		res, err := r.TransferBatch(req)
371		assertSaveFailureError(t, err)
372		if len(res.Items) != 0 || res.Replayed {
373			t.Fatalf("保存失败必须整体失败: %+v", res)
374		}
375	
376		// 原数据文件从未被替换：正常关闭并重新打开仍能读取整批前的状态。
377		if err := r.Close(); err != nil {
378			t.Fatal(err)
379		}
380		r2, err := Open(dir)
381		if err != nil {
382			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
383		}
384		t.Cleanup(func() { _ = r2.Close() })
385		assertBatchStillPending(t, r2)
386	
387		// 恢复保存条件后，在重开的登记册上用原请求重提：完整执行一次。
388		restoreBatchSave(t, r2)
389		assertBatchRetrySuccess(t, r2, req)
390	}
391	
392	// ---- 状态类业务拒绝的保存失败 ----
393	
394	// assertRejectSaveFailureResult 核对"拒绝结果保存失败"的返回：error 是保存
395	// 错误而非业务拒绝，结果与整批保存失败一致——没有转让条目、没有失败藏品
396	// 编号、不标回放、业务错误为空。
397	func assertRejectSaveFailureResult(t *testing.T, res TransferBatchResult, err error) {
398		t.Helper()
399		assertSaveFailureError(t, err)
400		if len(res.Items) != 0 || res.ItemID != "" || res.Replayed || res.Err != nil {
401			t.Fatalf("拒绝保存失败必须整体失败，结果应为空: %+v", res)
402		}
403	}
404	
405	// assertRequestFree 核对请求号未被占用、历史序号未被消耗。
406	func assertRequestFree(t *testing.T, r *Registry, req TransferBatchRequest, wantNextSeq int64) {
407		t.Helper()
408		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
409			t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
410		}
411		if r.state.NextSeq != wantNextSeq {
412			t.Fatalf("NextSeq = %d, want %d", r.state.NextSeq, wantNextSeq)
413		}
414	}
415	
416	// rejectSaveFailureReq 构造一个会被持有状态冲突拒绝的整批请求：i1 属于
417	// bob（版本 1）符合期望；i5 属于 carol（版本 1），与期望的 bob 不符，
418	// 整批按清单顺序报告最前的失败藏品 i5（ErrConflict）。
419	func rejectSaveFailureReq() TransferBatchRequest {
420		return tbtReq("rb-rej",
421			tbtEntry("i1", "carol", 1, 100),
422			tbtEntry("i5", "dave", 1, 200),
423		)
424	}
425	
426	// assertWorldUntouched 核对拒绝保存失败后所有藏品的持有、版本与历史保持
427	// 提交前内容（发行占用序号 1..5，无新增历史）。
428	func assertWorldUntouched(t *testing.T, r *Registry) {
429		t.Helper()
430		for id, owner := range map[string]string{
431			"i1": "bob", "i2": "bob", "i3": "bob", "i4": "bob", "i5": "carol",
432		} {
433			h, err := r.GetHolding(id)
434			if err != nil {
435				t.Fatalf("GetHolding %s: %v", id, err)
436			}
437			if h.OwnerID != owner || h.Version != 1 {
438				t.Fatalf("失败后 %s 持有被改变: %+v", id, h)
439			}
440			hist, err := r.History(id)
441			if err != nil {
442				t.Fatalf("History %s: %v", id, err)
443			}
444			if len(hist) != 1 || hist[0].Kind != "issue" {
445				t.Fatalf("失败后 %s 历史多出内容: %+v", id, hist)
446			}
447		}
448	}
449	
450	// TestTransferBatchRejectSaveFailureRetrySameState 覆盖：持有状态冲突的拒绝
451	// 落盘失败时返回保存错误、请求号不被占用；保存条件恢复且拒绝条件仍在时，
452	// 用完全相同的请求重提会重新保存此次拒绝，保存成功后才返回对应业务错误；
453	// 此后相同请求回放该拒绝。
454	func TestTransferBatchRejectSaveFailureRetrySameState(t *testing.T) {
455		r := mustCreate(t, tempDir(t))
456		setupBatchTransferWorld(t, r)
457		req := rejectSaveFailureReq()
458	
459		// 拒绝条件成立（i5 不属于 bob），但保存这次拒绝失败：返回保存错误，
460		// 不是 ErrConflict；结果为空；请求号不被这次未保存的拒绝占用。
461		blockBatchSave(t, r)
462		res, err := r.TransferBatch(req)
463		assertRejectSaveFailureResult(t, res, err)
464		assertRequestFree(t, r, req, 5)
465		assertWorldUntouched(t, r)
466	
467		// 保存条件恢复、拒绝条件仍在：重提重新保存此次拒绝，保存成功后返回
468		// 业务错误本身，并报告清单中最前的失败藏品。
469		restoreBatchSave(t, r)
470		res, err = r.TransferBatch(req)
471		if !errors.Is(err, ErrConflict) {
472			t.Fatalf("重提应在保存成功后返回业务拒绝 ErrConflict: %v", err)
473		}
474		if res.Replayed || res.ItemID != "i5" || !errors.Is(res.Err, ErrConflict) || len(res.Items) != 0 {
475			t.Fatalf("重提结果异常: %+v", res)
476		}
477		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; !ok {
478			t.Fatal("拒绝保存成功后应登记请求结果")
479		}
480		assertWorldUntouched(t, r)
481	
482		// 拒绝已保存：相同内容重提回放原拒绝，即使状态后来改变也不重新执行。
483		res, err = r.TransferBatch(req)
484		if !errors.Is(err, ErrConflict) || !res.Replayed || res.ItemID != "i5" ||
485			!errors.Is(res.Err, ErrConflict) {
486			t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
487		}
488	}
489	
490	// TestTransferBatchRejectSaveFailureRetryAfterStateChange 覆盖：未保存的
491	// 冲突拒绝不阻碍后续重提——保存条件恢复前，清单内藏品经另一笔合法转让
492	// 恰好变为请求期望的持有人与版本后，用完全相同的请求重提应正常执行，
493	// 不能回放那次未保存的冲突。
494	func TestTransferBatchRejectSaveFailureRetryAfterStateChange(t *testing.T) {
495		r := mustCreate(t, tempDir(t))
496		setupBatchTransferWorld(t, r)
497		// i5 期望 bob 持有版本 2：当前为 carol 版本 1，先被冲突拒绝。
498		req := tbtReq("rb-rej2",
499			tbtEntry("i1", "carol", 1, 100),
500			tbtEntry("i5", "dave", 2, 200),
501		)
502	
503		blockBatchSave(t, r)
504		res, err := r.TransferBatch(req)
505		assertRejectSaveFailureResult(t, res, err)
506		assertRequestFree(t, r, req, 5)
507	
508		// 保存条件恢复后，carol 把 i5 合法转让给 bob：i5 变为 bob 版本 2，
509		// 恰好满足原整批请求的期望持有人与版本。
510		restoreBatchSave(t, r)
511		if _, err := r.Transfer(TransferRequest{
512			Operator: "carol", Reason: "合法转让", RequestID: "rt-i5", ItemID: "i5",
513			ExpectedOwner: "carol", ExpectedVer: 1, ToID: "bob",
514		}); err != nil {
515			t.Fatal(err)
516		}
517	
518		// 用完全相同的原请求重提：按当前业务状态判断，整批正常执行一次，
519		// 不是回放那次未保存的冲突。
520		res, err = r.TransferBatch(req)
521		if err != nil {
522			t.Fatalf("状态满足后重提应正常执行，不能回放未保存的冲突: %v", err)
523		}
524		if res.Replayed || res.ItemID != "" || res.Err != nil || len(res.Items) != 2 {
525			t.Fatalf("重提结果异常: %+v", res)
526		}
527		if res.Items[0].ItemID != "i1" || res.Items[0].FromID != "bob" ||
528			res.Items[0].ToID != "carol" || res.Items[0].Version != 2 || res.Items[0].TxSeq != 7 {
529			t.Fatalf("第一件结果异常: %+v", res.Items[0])
530		}
531		if res.Items[1].ItemID != "i5" || res.Items[1].FromID != "bob" ||
532			res.Items[1].ToID != "dave" || res.Items[1].Version != 3 || res.Items[1].TxSeq != 8 {
533			t.Fatalf("第二件结果异常: %+v", res.Items[1])
534		}
535		if h, _ := r.GetHolding("i1"); h.OwnerID != "carol" || h.Version != 2 {
536			t.Fatalf("i1 持有异常: %+v", h)
537		}
538		if h, _ := r.GetHolding("i5"); h.OwnerID != "dave" || h.Version != 3 {
539			t.Fatalf("i5 持有异常: %+v", h)
540		}
541	
542		// 成功结果保存后，相同请求回放首次成功。
543		replay, err := r.TransferBatch(req)
544		if err != nil || !replay.Replayed || len(replay.Items) != 2 {
545			t.Fatalf("成功后重提应回放: %+v, err %v", replay, err)
546		}
547	}
548	
549	// TestTransferBatchRejectSaveFailureOperatorError 覆盖：操作者账户自身
550	// 有问题（停用）的拒绝落盘失败时同样返回保存错误、结果不附藏品编号；
551	// 保存恢复后重提重新保存拒绝并返回账户错误（ItemID 为空）。
552	func TestTransferBatchRejectSaveFailureOperatorError(t *testing.T) {
553		r := mustCreate(t, tempDir(t))
554		setupBatchTransferWorld(t, r)
555		if err := r.DeactivateAccount("bob"); err != nil {
556			t.Fatal(err)
557		}
558		req := tbtReq("rb-inactive", tbtEntry("i1", "carol", 1, 0))
559	
560		blockBatchSave(t, r)
561		res, err := r.TransferBatch(req)
562		assertRejectSaveFailureResult(t, res, err)
563		assertRequestFree(t, r, req, 5)
564		assertWorldUntouched(t, r)
565	
566		restoreBatchSave(t, r)
567		res, err = r.TransferBatch(req)
568		if !errors.Is(err, ErrAccountInactive) {
569			t.Fatalf("重提应在保存成功后返回 ErrAccountInactive: %v", err)
570		}
571		// 操作者账户自身有问题时不附藏品编号。
572		if res.ItemID != "" || !errors.Is(res.Err, ErrAccountInactive) || res.Replayed {
573			t.Fatalf("操作者账户错误的重提结果异常: %+v", res)
574		}
575	}
576	
577	// TestTransferBatchValidationErrorIgnoresSaveFailure 覆盖：参数错误与引用
578	// 不存在不占用请求号、不要求保存拒绝结果，即使存储暂时不可写也仍返回
579	// 原参数/引用错误，不能改报保存错误。
580	func TestTransferBatchValidationErrorIgnoresSaveFailure(t *testing.T) {
581		r := mustCreate(t, tempDir(t))
582		setupBatchTransferWorld(t, r)
583	
584		blockBatchSave(t, r)
585		defer restoreBatchSave(t, r)
586	
587		// 引用不存在的藏品：返回 ErrNotFound，不是保存错误。
588		notFoundReq := tbtReq("rb-nf", tbtEntry("nope", "carol", 1, 0))
589		res, err := r.TransferBatch(notFoundReq)
590		if !errors.Is(err, ErrNotFound) {
591			t.Fatalf("引用不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
592		}
593		if res.ItemID != "nope" || !errors.Is(res.Err, ErrNotFound) {
594			t.Fatalf("引用不存在的结果异常: %+v", res)
595		}
596		assertRequestFree(t, r, notFoundReq, 5)
597	
598		// 参数错误（负价款）：返回 ErrInvalidArgument，不是保存错误。
599		badReq := tbtReq("rb-bad", TransferBatchEntry{
600			ItemID: "i1", ToID: "carol", ExpectedOwner: "bob", ExpectedVer: 1, Price: -1,
601		})
602		if _, err := r.TransferBatch(badReq); !errors.Is(err, ErrInvalidArgument) {
603			t.Fatalf("参数错误应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
604		}
605		assertRequestFree(t, r, badReq, 5)
606	}
