94	// 通过后，先对全部条目检查编号占用，再按清单顺序逐件检查初始持有人——
95	// 因此即使前一件持有人未登记、后一件编号已占用，仍报告后一件编号被占用；
96	// 没有任何编号占用时，才报告清单顺序最前的持有人问题。任何一件不通过
97	// 则整批拒绝，返回值 itemID 指出问题所在的那件藏品。
98	func (r *Registry) checkBatchIssueEligibility(operator, seriesID string, entries []IssueBatchEntry) (string, error) {
99		if err := r.issueOperatorEligibility(operator); err != nil {
100			return "", err
101		}
102		if err := r.issueSeriesEligibility(seriesID, operator); err != nil {
103			return "", err
104		}
105		for _, e := range entries {
106			if err := r.issueItemAvailableEligibility(e.ItemID); err != nil {
107				return e.ItemID, err
108			}
109		}
110		for _, e := range entries {
111			if err := r.issueHolderEligibility(e.HolderID); err != nil {
112				return e.ItemID, err
113			}
114		}
115		return "", nil
